## Version

2.6.11
## Reproduction link

https://staging-flametree.techrino.net/

## Steps to reproduce
#### The vue instance
```js

window.app = new Vue({
    el : "#flametree-app",
    components,
    store: store,
    data: {
        mmenuState: {
            ready: false
        }
    },
    methods: {
        initializeMMenu(){
            let mmenu =  new Mmenu("#flametree-side-drawer", {

                wrappers: ["bootstrap"],
                "extensions": [
                    "pagedim-black",
                    "position-front"
                ],
                offCanvas: {
                    page: {
                        selector: "#page-content"
                    }
                }
            });
            this.mmenuState.ready = true;

            this.$store.commit('SideDrawer/setMenu', mmenu);

            this.displayMenu();
        },

        displayMenu: function(){
            document.getElementById('flametree-side-drawer').classList.remove('d-none')
        },
        activateMegaMenu: function () {
            this.$store.commit('Navbar/activateMegaMenu');

        },
        deactivateMegaMenu: function(){

            this.$store.commit('Navbar/deactivateMegaMenu');


        },

        getDisplayMegaMenuClass: function(){
            if(this.megaMenuState){
                return 'd-flex'
            } else {
                return 'd-none'
            }
        }
    },
    mounted: function () {
        this.initializeMMenu();
    },
    computed: {

        megaMenuState(){
            return this.$store.getters['Navbar/currentMegaMenuState']
        }
    }
})


```
### The VueX store instance

```js

export default  {
    namespaced: true,
    state: {
        showProductsMegaMenu: false,
        currentSelectedMenu: null
    },
    mutations: {
        deactivateMegaMenu: function(state){
            state.showProductsMegaMenu = false;
        },
        activateMegaMenu: function(state) {
            state.showProductsMegaMenu = true;
        },
        setCurrentSelectedMenu: function (state, _val) {
            state.currentSelectedMenu = _val;
        }
    },
    actions: {

    },
    getters: {
        currentMegaMenuState: function(state){
            return state.showProductsMegaMenu;
        },
        getCurrentSelectedMenu: function(state){
            return state.currentSelectedMenu;
        }
    }
}


```
#### The Mega Menu element
```html
    <div :class='(megaMenuState) ? "d-flex" : "d-none" '
          @mouseleave="deactivateMegaMenu()"
          @mouseenter="activateMegaMenu()">

        <mega-menu>
            {%  for index, producer_category in producer_categories %}
                <sidebar-menu-item key="{{ index}}" title="{{ producer_category.title }}" link="{{ "/products/#"~producer_category.title  }}">
                    {%  if producer_category.items %}
                        {%  for producer in producer_category.items %}
                            <menu-item
                                leading-icon="fas fa-chevron-circle-right"
                                parent="{{ producer_category.title }}"
                                title="{{ producer.title }}"
                                description="{{ producer.viewBag.origin }}"
                                icon="fas fa-map-marker-alt fa-2x"
                            >
                            </menu-item>

                        {% endfor %}
                    {%  endif %}
                </sidebar-menu-item>
            {%  endfor %}

        </mega-menu>
    </div>


```
## What is expected?

In Firefox, Chrome the mega menu get displayed when the mouseover event is fired on the link "Producer" dynamic class binding goes well without any issue.

## What is actually happening?

In Safari, when the mouseover fired by hovering on the link "Producer" the mega menu isn't get displayed since the 'd-flex' class didn't get bind into the DOM element dynamically.

After debugging the mouseover and mouseenter event work fine it seems to be after the VueX state / VueJS data state get updated, the DOM attribute doesn't get rebuild in Safari and there is no error message get output at Safari console.

